<?php
/** UX in VR and XR: presence and comfort, motion sickness and locomotion, spatial interfaces, input and interaction. */

return [
    'id' => 'ux-vr', 'family' => 'ux', 'after' => 'ux-intermediate', 'categories' => ['design'],
    'title' => L('UX in realtà virtuale', 'UX in VR'), 'short' => L('UX in VR', 'VR UX'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Progettare esperienze immersive in VR, AR e realtà mista: presenza e comfort, chinetosi e locomozione, interfacce spaziali, mani, controller, sguardo e voce.', 'Designing immersive experiences in VR, AR and mixed reality: presence and comfort, motion sickness and locomotion, spatial interfaces, hands, controllers, gaze and voice.'),
    'lessons' => [
        lesson('presence', L('Presenza, VR, AR e realtà mista', 'Presence, VR, AR and mixed reality'), [
            P('La **realtà virtuale** (VR) sostituisce ciò che vedi con un mondo digitale; la **realtà aumentata** (AR) aggiunge oggetti digitali al mondo reale (anche dal telefono); la **realtà mista** (MR) li fa interagire con lo spazio vero, come su Meta Quest o Apple Vision Pro. Insieme si chiamano **XR**.', '**Virtual reality** (VR) replaces what you see with a digital world; **augmented reality** (AR) adds digital objects to the real world (even from a phone); **mixed reality** (MR) makes them interact with real space, as on Meta Quest or Apple Vision Pro. Together they are called **XR**.'),
            P('L’obiettivo della VR è la **presenza**: la sensazione di essere davvero lì. Si rompe facilmente: ritardo tra movimento della testa e immagine (**latenza**), frame rate basso, mani che non seguono, oggetti che si compenetrano. Per questo le prestazioni sono parte della UX: serve un frame rate stabile (72-90 fps o più).', 'The goal of VR is **presence**: the feeling of really being there. It breaks easily: delay between head movement and image (**latency**), low frame rate, hands that do not follow, objects passing through each other. That is why performance is part of UX: a stable frame rate (72-90 fps or more) is needed.'),
        ], [
            Q('p1', L('Che differenza c’è tra VR e AR?', 'What is the difference between VR and AR?'), [L('La VR sostituisce il mondo, l’AR lo arricchisce', 'VR replaces the world, AR enriches it'), L('Sono la stessa cosa', 'They are the same'), L('L’AR richiede sempre un visore', 'AR always requires a headset'), L('La VR funziona solo all’aperto', 'VR works only outdoors')], 0, L('Sostituire o aggiungere.', 'Replace or add.')),
            Q('p2', L('Che cos’è la presenza?', 'What is presence?'), [L('La sensazione di essere davvero lì', 'The feeling of really being there'), L('Il numero di utenti online', 'The number of online users'), L('La batteria del visore', 'The headset battery'), L('Un tipo di controller', 'A kind of controller')], 0, L('Fragile e preziosa.', 'Fragile and precious.')),
            Q('p3', L('Che cosa rompe la presenza?', 'What breaks presence?'), [L('Latenza e frame rate basso', 'Latency and low frame rate'), L('Un buon audio spaziale', 'Good spatial audio'), L('Mani tracciate bene', 'Well-tracked hands'), L('Ombre realistiche', 'Realistic shadows')], 0, L('Le prestazioni sono UX.', 'Performance is UX.')),
        ], task('text', L('Classifica tre esperienze come `VR`, `AR` o `MR`, una per riga nel formato `esperienza: tipo`: provare un divano in salotto dal telefono, un gioco in un castello che sostituisce la stanza, una finestra virtuale appoggiata sulla scrivania vera che resta lì quando giri.', 'Classify three experiences as `VR`, `AR` or `MR`, one per line in the format `experience: type`: trying a sofa in the living room from a phone, a game in a castle replacing the room, a virtual window resting on the real desk that stays put when you turn.'), '', [re('(divano|sofa)[^\n]*:\s*AR\b', L('Il divano è AR', 'The sofa is AR')), re('(castello|castle)[^\n]*:\s*VR\b', L('Il castello è VR', 'The castle is VR')), re('(finestra|window|scrivania|desk)[^\n]*:\s*MR\b', L('La finestra sulla scrivania è MR', 'The window on the desk is MR'))], '', "divano in salotto: AR\ngioco nel castello: VR\nfinestra sulla scrivania: MR"), [
            dMatch(pMatch(), [['VR', L('Sostituisce il mondo', 'Replaces the world')], ['AR', L('Aggiunge al mondo', 'Adds to the world')], ['MR', L('Interagisce con lo spazio vero', 'Interacts with real space')], ['XR', L('Tutte insieme', 'All of them')], [L('Presenza', 'Presence'), L('Sentirsi lì', 'Feeling there')]], L('Le realtà estese.', 'Extended realities.')),
            dFlash(pFlash(), [[L('L’AR può funzionare anche da telefono', 'AR can work from a phone too'), true], [L('Il frame rate non influisce sull’esperienza', 'Frame rate does not affect the experience'), false], [L('La latenza può rompere la presenza', 'Latency can break presence'), true], [L('VR e AR sono sinonimi', 'VR and AR are synonyms'), false]], L('Immersione.', 'Immersion.')),
        ]),
        lesson('comfort', L('Comfort, chinetosi e locomozione', 'Comfort, motion sickness and locomotion'), [
            P('La **chinetosi** (cybersickness) nasce quando gli occhi vedono movimento ma il corpo non lo sente: nausea, sudore, mal di testa. Le cause principali sono il movimento artificiale fluido, le accelerazioni, le rotazioni della telecamera non volute dall’utente. **Regola d’oro**: non muovere mai la telecamera al posto della testa dell’utente.', '**Motion sickness** (cybersickness) arises when the eyes see movement but the body does not feel it: nausea, sweating, headache. The main causes are smooth artificial movement, acceleration, camera rotations not chosen by the user. **Golden rule**: never move the camera in place of the user’s head.'),
            P('Per spostarsi si usano tecniche di **locomozione** comode: il **teletrasporto** (punti e scompari lì), la **rotazione a scatti** (snap turn) invece di quella fluida, la **vignettatura** che restringe la vista durante il movimento, il movimento reale in **room scale**. Offri sempre opzioni di comfort e la scelta tra seduto e in piedi.', 'To move around you use comfortable **locomotion** techniques: **teleportation** (point and vanish there), **snap turning** instead of smooth rotation, **vignetting** that narrows the view during movement, real movement in **room scale**. Always offer comfort options and the choice between seated and standing.'),
            Tip('Anche le sessioni contano: suggerisci pause, evita lampi e sfarfallii, e non chiedere di tenere le braccia alzate a lungo (il “braccio da gorilla” stanca in pochi minuti).', 'Sessions matter too: suggest breaks, avoid flashes and flicker, and do not ask users to hold their arms up for long (“gorilla arm” tires in minutes).'),
        ], [
            Q('c1', L('Da che cosa nasce la chinetosi in VR?', 'What causes motion sickness in VR?'), [L('Gli occhi vedono movimento, il corpo no', 'Eyes see motion, the body does not'), L('Dal volume troppo alto', 'From volume too high'), L('Dai colori troppo vivaci', 'From colours too bright'), L('Dal visore troppo leggero', 'From a headset too light')], 0, L('Un conflitto dei sensi.', 'A sensory conflict.')),
            Q('c2', L('Quale locomozione è più comoda per molti utenti?', 'Which locomotion is more comfortable for many users?'), [L('Il teletrasporto', 'Teleportation'), L('Il movimento fluido veloce', 'Fast smooth movement'), L('Le montagne russe automatiche', 'Automatic roller coasters'), L('La rotazione continua della telecamera', 'Continuous camera rotation')], 0, L('Niente accelerazioni percepite.', 'No perceived acceleration.')),
            Q('c3', L('Che cos’è il braccio da gorilla?', 'What is gorilla arm?'), [L('La fatica di tenere le braccia alzate', 'The fatigue of holding arms up'), L('Un avatar scimmia', 'A monkey avatar'), L('Un controller grande', 'A big controller'), L('Un gesto di vittoria', 'A victory gesture')], 0, L('Interfacce in basso e vicine.', 'Interfaces low and close.')),
        ], task('text', L('Scrivi tre opzioni di comfort per un gioco VR di esplorazione, una per riga con `-`, tra cui il **teletrasporto** e la **rotazione a scatti**.', 'Write three comfort options for a VR exploration game, one per line with `-`, including **teleportation** and **snap turning**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre opzioni', 'Three options')), re('teletrasport|teleport', L('Il teletrasporto', 'Teleportation')), re('scatt|snap', L('La rotazione a scatti', 'Snap turning'))], '', "- teletrasporto al posto del movimento fluido\n- rotazione a scatti di 30 gradi\n- vignettatura durante gli spostamenti"), [
            dMatch(pMatch(), [[L('Teletrasporto', 'Teleportation'), L('Spostarsi senza accelerare', 'Moving without accelerating')], ['Snap turn', L('Rotazione a scatti', 'Stepped rotation')], [L('Vignettatura', 'Vignetting'), L('Vista ristretta in movimento', 'Narrowed view while moving')], ['Room scale', L('Camminare davvero', 'Really walking')], [L('Braccio da gorilla', 'Gorilla arm'), L('Fatica delle braccia alzate', 'Fatigue of raised arms')]], L('Stare bene in VR.', 'Feeling well in VR.')),
            dFlash(pFlash(), [[L('Muovere la telecamera al posto della testa causa nausea', 'Moving the camera instead of the head causes nausea'), true], [L('Le accelerazioni rendono la VR più comoda', 'Acceleration makes VR more comfortable'), false], [L('Va offerta la scelta tra seduto e in piedi', 'The choice of seated or standing should be offered'), true], [L('I lampi rapidi sono innocui in VR', 'Rapid flashes are harmless in VR'), false]], L('Comfort prima di tutto.', 'Comfort first.')),
        ]),
        lesson('spatial', L('Interfacce spaziali', 'Spatial interfaces'), [
            P('In XR l’interfaccia vive nello **spazio 3D**. I pannelli si mettono a una **distanza comoda** (circa 1-3 metri), poco sotto l’altezza degli occhi, dentro il **campo visivo** centrale: niente testi agli angoli, dove si leggono male e costringono a girare la testa. Il testo deve essere grande e ad alto contrasto, perché la risoluzione del visore è limitata.', 'In XR the interface lives in **3D space**. Panels go at a **comfortable distance** (about 1-3 metres), slightly below eye level, within the central **field of view**: no text in the corners, where it reads poorly and forces head turning. Text must be large and high-contrast, because headset resolution is limited.'),
            P('Esistono interfacce **diegetiche** (parte del mondo: un orologio al polso dell’avatar, una mappa in mano) e **non diegetiche** (pannelli fluttuanti). Un HUD incollato alla vista come nei giochi su schermo è scomodo in VR: meglio elementi **ancorati al mondo** o al corpo. L’**audio spaziale** guida l’attenzione verso ciò che succede fuori dalla vista.', 'There are **diegetic** interfaces (part of the world: a watch on the avatar’s wrist, a map in hand) and **non-diegetic** ones (floating panels). A HUD glued to the view as in screen games is uncomfortable in VR: elements **anchored to the world** or the body work better. **Spatial audio** guides attention to what happens out of view.'),
        ], [
            Q('s1', L('Dove posizionare un pannello di testo in VR?', 'Where to place a text panel in VR?'), [L('A 1-3 metri, nel campo visivo centrale', 'At 1-3 metres, in the central field of view'), L('Incollato agli occhi', 'Glued to the eyes'), L('Dietro l’utente', 'Behind the user'), L('In un angolo in alto', 'In a top corner')], 0, L('Comodo da leggere.', 'Comfortable to read.')),
            Q('s2', L('Che cos’è un’interfaccia diegetica?', 'What is a diegetic interface?'), [L('Un’interfaccia che fa parte del mondo', 'An interface that is part of the world'), L('Un menu di pausa', 'A pause menu'), L('Un HUD fisso', 'A fixed HUD'), L('Un sottotitolo', 'A subtitle')], 0, L('Come un orologio al polso.', 'Like a watch on the wrist.')),
            Q('s3', L('A che cosa serve l’audio spaziale?', 'What is spatial audio for?'), [L('Guidare l’attenzione fuori dalla vista', 'Guiding attention out of view'), L('Risparmiare batteria', 'Saving battery'), L('Sostituire i testi', 'Replacing text'), L('Nulla', 'Nothing')], 0, L('Il suono indica la direzione.', 'Sound points the way.')),
        ], task('text', L('Descrivi la posizione di un menu in VR su tre righe: `distanza: `, `altezza: `, `ancoraggio: ` (mondo, corpo o vista).', 'Describe a VR menu’s position on three lines: `distance: `, `height: `, `anchoring: ` (world, body or view).'), '', [re('^(distanza|distance)\s*:\s*.*\b[1-3]([.,]\d)?\s*(m|metr)', L('Tra 1 e 3 metri', 'Between 1 and 3 metres')), re('^(altezza|height)\s*:\s*.*(sotto|below|occhi|eye)', L('Rispetto agli occhi', 'Relative to the eyes')), re('^(ancoraggio|anchoring)\s*:\s*.*(mondo|world|corpo|body|polso|wrist)', L('Ancorato al mondo o al corpo', 'Anchored to world or body'))], '', "distanza: 1,5 m\naltezza: poco sotto gli occhi\nancoraggio: al mondo, davanti all’utente"), [
            dMatch(pMatch(), [[L('Diegetica', 'Diegetic'), L('Parte del mondo', 'Part of the world')], [L('Non diegetica', 'Non-diegetic'), L('Pannello fluttuante', 'Floating panel')], [L('Ancorato al mondo', 'World-anchored'), L('Resta nello spazio', 'Stays in space')], [L('Audio spaziale', 'Spatial audio'), L('Guida lo sguardo', 'Guides the gaze')]], L('Interfacce nello spazio.', 'Interfaces in space.')),
            dFlash(pFlash(), [[L('In VR il testo deve essere più grande che su schermo', 'In VR text must be larger than on screen'), true], [L('Un HUD incollato alla vista è sempre comodo', 'A HUD glued to the view is always comfortable'), false], [L('I testi agli angoli della vista si leggono male', 'Text in the corners of view reads poorly'), true], [L('La risoluzione dei visori è illimitata', 'Headset resolution is unlimited'), false]], L('Progettare in 3D.', 'Designing in 3D.')),
        ]),
        lesson('input', L('Mani, controller, sguardo e voce', 'Hands, controllers, gaze and voice'), [
            P('In XR si interagisce in molti modi: **controller** (precisi, con pulsanti e vibrazione), **mani tracciate** (naturali ma senza feedback tattile), **sguardo** (gli occhi puntano, un gesto o un pizzico conferma, come su Vision Pro), **voce**. Gli oggetti vicini si **toccano direttamente**, quelli lontani si puntano con un **raggio**.', 'In XR there are many ways to interact: **controllers** (precise, with buttons and vibration), **tracked hands** (natural but without tactile feedback), **gaze** (eyes point, a gesture or pinch confirms, as on Vision Pro), **voice**. Nearby objects are **touched directly**, distant ones are pointed at with a **ray**.'),
            P('Senza tatto, il **feedback** deve arrivare da altri sensi: evidenziazione quando si punta, suono al tocco, vibrazione del controller, oggetti che reagiscono. Con lo sguardo attenzione al problema del **Re Mida**: tutto ciò che guardi non deve attivarsi, serve una conferma esplicita. E pensa all’**accessibilità**: chi non può alzarsi, usare due mani o muovere la testa deve avere alternative.', 'Without touch, **feedback** must come from other senses: highlighting when pointing, sound on touch, controller vibration, objects that react. With gaze beware the **Midas touch** problem: not everything you look at should activate, an explicit confirmation is needed. And think of **accessibility**: those who cannot stand, use two hands or move their head need alternatives.'),
        ], [
            Q('i1', L('Come si interagisce con un oggetto lontano?', 'How do you interact with a distant object?'), [L('Puntandolo con un raggio', 'Pointing at it with a ray'), L('Camminando per chilometri', 'Walking for kilometres'), L('Non si può', 'You cannot'), L('Solo a voce, sempre', 'Only by voice, always')], 0, L('Vicino si tocca, lontano si punta.', 'Near you touch, far you point.')),
            Q('i2', L('Che cos’è il problema del Re Mida con lo sguardo?', 'What is the Midas touch problem with gaze?'), [L('Si attiva tutto ciò che si guarda', 'Everything you look at activates'), L('Gli oggetti diventano d’oro', 'Objects turn to gold'), L('Lo sguardo non viene tracciato', 'Gaze is not tracked'), L('Il visore si scarica', 'The headset runs flat')], 0, L('Serve una conferma.', 'A confirmation is needed.')),
            Q('i3', L('Che cosa manca alle mani tracciate rispetto ai controller?', 'What do tracked hands lack compared to controllers?'), [L('Il feedback tattile', 'Tactile feedback'), L('La naturalezza', 'Naturalness'), L('Le dita', 'Fingers'), L('Il colore', 'Colour')], 0, L('Il feedback arriva da vista e suono.', 'Feedback comes from sight and sound.')),
        ], task('text', L('Per un pulsante virtuale premuto con le mani tracciate, scrivi tre tipi di feedback, uno per riga con `-`: uno **visivo**, uno **sonoro** e un altro a scelta.', 'For a virtual button pressed with tracked hands, write three kinds of feedback, one per line with `-`: one **visual**, one **audio** and another of your choice.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre feedback', 'Three kinds of feedback')), re('evidenz|illumin|colore|luce|highlight|glow|colou?r|visiv|visual|si abbassa|moves', L('Uno visivo', 'A visual one')), re('suon|click|clic|audio|sound', L('Uno sonoro', 'An audio one'))], '', "- il pulsante si illumina quando il dito si avvicina\n- un suono di click alla pressione\n- il pulsante si abbassa come uno vero"), [
            dMatch(pMatch(), [['Controller', L('Precisi, con vibrazione', 'Precise, with vibration')], [L('Mani tracciate', 'Tracked hands'), L('Naturali, senza tatto', 'Natural, no touch')], [L('Sguardo e pizzico', 'Gaze and pinch'), L('Guardi e confermi', 'Look and confirm')], [L('Raggio', 'Ray'), L('Oggetti lontani', 'Distant objects')], [L('Voce', 'Voice'), L('Comandi senza mani', 'Hands-free commands')]], L('Modi di interagire.', 'Ways to interact.')),
            dFlash(pFlash(), [[L('Con le mani tracciate il feedback visivo e sonoro è essenziale', 'With tracked hands visual and audio feedback is essential'), true], [L('Con lo sguardo tutto deve attivarsi appena guardato', 'With gaze everything should activate as soon as looked at'), false], [L('Gli oggetti vicini si possono toccare direttamente', 'Nearby objects can be touched directly'), true], [L('L’accessibilità non riguarda la VR', 'Accessibility does not concern VR'), false]], L('Interazione naturale.', 'Natural interaction.')),
        ]),
        lesson('onboarding', L('Primo accesso, accessibilità e test in VR', 'First run, accessibility and testing in VR'), [
            P('Molte persone indossano un visore per la prima volta: il **primo accesso** deve insegnare i gesti uno alla volta, facendoli provare subito in una scena tranquilla. Mostra dove sono i limiti dello spazio sicuro e come uscire in ogni momento.', 'Many people put on a headset for the first time: the **first run** must teach gestures one at a time, letting people try them right away in a calm scene. Show where the safe-space limits are and how to leave at any moment.'),
            P('**Accessibilità in VR**: modalità seduta, regolazione dell’altezza, comandi con una mano sola, sottotitoli che seguono lo sguardo, alternative al movimento fluido. I **test** si fanno con il visore addosso e brevi: osserva segnali di malessere e chiedi di pensare ad alta voce.', '**Accessibility in VR**: seated mode, height adjustment, one-handed controls, subtitles that follow the gaze, alternatives to smooth movement. **Tests** are done with the headset on and kept short: watch for signs of discomfort and ask people to think aloud.'),
        ], [
            Q('vo1', L('Come si insegnano i gesti al primo accesso?', 'How are gestures taught on first run?'), [L('Uno alla volta, provandoli subito', 'One at a time, trying them right away'), L('Tutti in un video lungo', 'All in a long video'), L('In un manuale PDF', 'In a PDF manual'), L('Non si insegnano', 'They are not taught')], 0, L('Imparare facendo.', 'Learning by doing.')),
            Q('vo2', L('Quale è una scelta accessibile in VR?', 'Which is an accessible choice in VR?'), [L('Una modalità seduta', 'A seated mode'), L('Solo comandi a due mani', 'Two-handed controls only'), L('Movimento fluido obbligatorio', 'Mandatory smooth movement'), L('Nessun sottotitolo', 'No subtitles')], 0, L('Non tutti possono stare in piedi.', 'Not everyone can stand.')),
            Q('vo3', L('Come devono essere le sessioni di test?', 'How should test sessions be?'), [L('Brevi, osservando il malessere', 'Short, watching for discomfort'), L('Lunghe ore senza pause', 'Long hours without breaks'), L('Senza visore', 'Without a headset'), L('Solo con questionari', 'Only with questionnaires')], 0, L('Il comfort prima di tutto.', 'Comfort first.')),
        ], task('text', L('Scrivi tre opzioni di accessibilità per un’app VR, una per riga con `-`, tra cui una `seduta`.', 'Write three accessibility options for a VR app, one per line with `-`, including a `seduta` (seated) one.'), '', [re('^-\s*\S.{4,}\n-\s*\S.{4,}\n-\s*\S.{4,}', L('Tre opzioni', 'Three options')), re('sedut', L('C’è la modalità seduta', 'Seated mode is there'))], '', "- Modalità seduta\n- Sottotitoli che seguono lo sguardo\n- Teletrasporto al posto del movimento fluido"), [
            dOrder(pSort(), [L('Regola altezza e spazio', 'Set height and space'), L('Mostra come uscire', 'Show how to leave'), L('Insegna il primo gesto', 'Teach the first gesture'), L('Fallo provare', 'Let them try it'), L('Passa al gesto successivo', 'Move to the next gesture')], L('Un buon primo accesso.', 'A good first run.')),
            dFlash(pFlash(), [[L('In VR serve sempre un modo per uscire', 'VR always needs a way out'), true], [L('Le sessioni di test lunghe sono più utili', 'Long test sessions are more useful'), false], [L('I comandi a una mano aiutano molte persone', 'One-handed controls help many people'), true], [L('Il primo accesso deve spiegare tutto insieme', 'First run should explain everything at once'), false]], L('VR per tutti.', 'VR for everyone.')),
        ]),
    ],
];
